    ['code' => 'teach-behaviour', 'prof' => 'teacher', 'type' => 'situational', 'lvl' => [1, 4], 'diff' => 3, 'sec' => 180, 'skills' => ['conflict_management', 'communication'],
        'fr' => ['Un élève perturbe régulièrement la classe. Comment réagissez-vous ?', 'Règles, entretien individuel, compréhension des causes, lien avec la famille et l\'équipe.',
